"utc-offset": {
  toICAL: function(aValue) {
    if (aValue.length < 7) {
      // no seconds
      // -0500
      return aValue.slice(0, 3) +
             aValue.slice(4, 6);
    } else {
      // seconds
      // -050000
      return aValue.slice(0, 3) +
             aValue.slice(4, 6) +
             aValue.slice(7, 9);
    }
  },

  fromICAL: function(aValue) {
    if (aValue.length < 6) {
      // no seconds
      // -05:00
      return aValue.slice(0, 3) + ':' +
             aValue.slice(3, 5);
    } else {
      // seconds
      // -05:00:00
      return aValue.slice(0, 3) + ':' +
             aValue.slice(3, 5) + ':' +
             aValue.slice(5, 7);
    }
  },
